export function getUclPlayerById(id: string): Player | undefined {
  return UCL_COMPLETE_REGISTRY[id];
}

export function getAllUclPlayers(): Player[] {
  const seen = new Set<string>();
  const list: Player[] = [];
  for (const player of Object.values(UCL_COMPLETE_REGISTRY)) {
    const norm = player.name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
    if (!seen.has(norm)) {
      seen.add(norm);
      list.push(player);
    }
  }
  return list;
}
